/* Undefined Behavior: Multiple unsequenced side effects */
int i = 5;
i = i++ + ++i; // UB (C/C++), modifies i twice

/* Sequence Points: Use comma operator or separate statements */
int j = 5;
j = (j++, j + 1); // Sequenced by comma (j=6, result=7)

/* UB: Function argument evaluation order (unspecified) */
int k = 0;
// k's value for f depends on compiler
f(k++, k);

/* UB: Accessing variable after free (Dangling pointer) */
int* p = malloc(sizeof(int));
free(p);
*p = 10; // UB

/* UB: Pointer arithmetic outside array bounds */
int arr[10];
int* end = arr + 10;
*(end + 1) = 42; // UB

/* UB: Shifting into sign bit of signed type */
int s = 1 << 31; // UB if int is 32-bit signed

/* Defined: Separate statements guarantee sequencing */
int a = 5;
int b = a++; // b=5, a=6
a += ++b; // a=6, b=6 -> a = 12
